+ 
 
   
     
     
     Latah County Places of Interest - 4.11 

     
     

     
      html,
      body,
      #viewDiv {
        padding: 0;
        margin: 0;
        height: 100%;
        width: 100%;
      }
     

     
      require([
        "esri/Map",
        "esri/views/MapView",
        "esri/layers/FeatureLayer",
		"esri/widgets/BasemapGallery",
		"esri/widgets/Expand",
		"esri/widgets/LayerList",
		"esri/widgets/Search",
		"esri/PopupTemplate",
		"esri/widgets/Print",

      ], function(Map, MapView, FeatureLayer, BasemapGallery, Expand, LayerList, Search, PopupTemplate, Print) {
        var map = new Map({
          basemap: "topo"
        });

        var view = new MapView({
          container: "viewDiv",
		container: "viewDiv",  // Reference to the scene div created in step 5
		map: map,  // Reference to the map object created before the scene
		zoom: 10,  // Sets zoom level based on level of detail (LOD)
		center: [-116.711679789558, 46.8161275055622],
		popup: {
		dockEnabled: true,
		dockOptions: {
        buttonEnabled: false,
        breakpoint: false
          }
        }
        });

        /********************
         * Add Popup Templates
         ********************/
		 // autocasts as new PopupTemplate() this one is for the cemeteries layer
		var template = {
          title: "Cemeteries",
          content: [{
          type: "fields",
          fieldInfos: []
        }, {
          type: "text",
          text: "<p>The <b>{Name}</b>{Alias} is a {Category} maintained by the <b>{District}</b>, and is found {Limits} the community of {City}.</p>" +
          "<ul><li> The physical address of this {Category} is: {Location} {City} {Zip} </li>" +
          "<li>{Directions}</li>" +
          "<li><a target='blank' href='https://www.findagrave.com/cgi-bin/fg.cgi?page=csr&CScn=&CScntry=4&CSst=15&CScnty=674'>Find more information at findagrave.com</a></li></ul>",
          }, {
          type: "media",
          mediaInfos: [{
          title: "<b>{Name}</b>",
          type: "image",
          value: {
           sourceURL: "{Link}" 
              } 
            }]
          }, {
            type: "attachments"
          }]
        };
		 
		//2nd PopupTemplate() this one is for the historic places layer	
		var template2 = new PopupTemplate({
          title: "Historic Places",
          content: [{
          type: "fields",
          fieldInfos: []
          }, {
          type: "text",
          text: "<p>The <b>{Name}</b> was added to the National Register of Historic Places on {Date}, this {Category} is located {Limits} the community of {City}.</p>" +
		  "<ul><li> The physical address of this {Category} is: {Location}, {City} {Zip} </li>" +
		  "<li><a href={Link}>Click here for More information</a></li><ul>",
          }, {
          type: "media",
          mediaInfos: [{
          title: "<b>{Name}</b>",
          type: "image",
          value: {
          sourceURL: "{Image}"
              }
            }]
          }, {
            type: "attachments"
          }]
        }); 
		 

		
		//3nd PopupTemplate() this one is for the historic districts layer	
		var template3 = new PopupTemplate({
         title: "Districts of Note",
         content: [{
         type: "fields",
         fieldInfos: []
         }, {
         type: "text",
         text: "<p>The <b>{Name}</b> was added to the National Register of Historic Places on {Date}, this {Category} is located {Limits} the community of {City}.</p>" +
		 "<ul><li><a href={Link}>Click here for More information</a></li>" +
		 "<li><a href={Link2}>Or, click here for even More information</a></li><ul>",
         }, {
         type: "media",
         mediaInfos: [{
         title: "<b>{Name}</b>",
         type: "image",
         value: {
         sourceURL: "{Image}"
              }
            }]
          }, {
            type: "attachments"
          }]
        });
		
		//popup for Recreation Sites
		//4th PopupTemplate() this one is for the Recreation Sites layer	
		var template4 = new PopupTemplate({
         title: "Recreation Sites",
         content: [{
         type: "fields",
         fieldInfos: []
         }, {
         type: "text",
         text: "<p><b>{Name}</b> is a {Type_} maintained by {Agency}. It can be found {Address}, {Loc} {City}.</p>" +
		 "<ul><li><a href={Link}>Click here for More information</a></li>",
         }, {
         type: "media",
         mediaInfos: [{
         title: "<b>{Name}</b>",
         type: "image",
         value: {
         sourceURL: "{Image2}"
              }
            }]
          }, {
            type: "attachments"
          }]
        });
		

		
		//5th PopupTemplate() this one is for the Trails layer	
		var template5 = new PopupTemplate({
         title: "Trails",
         content: [{
         type: "fields",
         fieldInfos: []
         }, {
         type: "text",
         text: "<p><b>{Name}</b>: {Description}</p>" +
		 "<ul><li><a href={Link}>Click here for More information</a></li>",
         }, {
         type: "media",
         mediaInfos: [{
         title: "<b>{Name}</b>",
         type: "image",
         value: {
         sourceURL: "{Image2}"
              }
            }]
          }, {
            type: "attachments"
          }]
        });		
		
//6th PopupTemplate() this one is for the Recreation Districts layer	
		var template6 = new PopupTemplate({
         title: "Recreation Districts",
         content: [{
         type: "fields",
         fieldInfos: []
         }, {
         type: "text",
         text: "<p><b>{Name}</b>: {Description}</p>" +
		 "<ul><li><a href={Link}>Click here for More information</a></li>",
         }, {
         type: "media",
         mediaInfos: [{
         title: "<b>{Name}</b>",
         type: "image",
         value: {
         sourceURL: "{Image2}"
              }
            }]
          }, {
            type: "attachments"
          }]
        });	

				
		/********************
         * Add feature layers
         ********************/

        //Parcel Polygons
        var Parcels = new FeatureLayer({
		listMode: "hide",
        url: "https://gis.latah.id.us/arcgis/rest/services/Parcels1/MapServer/0",
		labelsVisible: false
        });
        map.add(Parcels);
		
		// Sections   
		var Sections = new FeatureLayer({
		listMode: "hide",
        url: "https://gis.latah.id.us/arcgis/rest/services/Cadastral_Data_/MapServer/2"
        });
        map.add(Sections);
		
		// Townships  
        var Townships = new FeatureLayer({
		listMode: "hide",
        url: "https://gis.latah.id.us/arcgis/rest/services/Cadastral_Data_/MapServer/1"
        });
        map.add(Townships); 
		
		// PLSS Labels  		
		var Labels = new FeatureLayer({
		listMode: "hide",
        url: "https://gis.latah.id.us/arcgis/rest/services/Cadastral_Data_/MapServer/0"
        });
        map.add(Labels);
				
		// Public and Private cemeteries 
		var Cemeteries = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/LatahView2/MapServer/0",
		title: "Cemeteries",
		popupTemplate: template
		});
		map.add(Cemeteries); 
 
		// Registered historic places
		var HistoricPlaces = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/LatahView2/MapServer/1",
		title: "Historic Places",
		popupTemplate: template2
		}); 
		map.add(HistoricPlaces);
 
		// Historic Districts
		var HistoricDistricts = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/LatahView2/MapServer/2",
		title: "Historic Districts",
		popupTemplate: template3
		}); 
		map.add(HistoricDistricts);
		
		// Recreation Sites
		var Recreation = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/LatahView2/MapServer/3",
		title: "Recreation Sites",
		popupTemplate: template4
		});
		map.add(Recreation);

		
		// Walking Trails	
		var Trails = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/LatahView2/MapServer/4",
		title: "Trails",
		popupTemplate: template5
		}); 
		map.add(Trails);
		
		// Recreation Districts	
		var RecreationDistricts = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/LatahView2/MapServer/5",
		title: "Recreation Districts",
		opacity: 0.6,
		popupTemplate: template6
		}); 
		map.add(RecreationDistricts);
		
		
		
		
	
		
		

        /********************
         * Add UI Elements
         ********************/
		// Begin adding UI elements here
		// create base map gallery
		var basemapGallery = new BasemapGallery({
		view: view,
		container: document.createElement("div")
		});    
		// create container for base map gallery 
		var bgExpand = new Expand({
		view: view,
		content: basemapGallery
		}); 
		// add container with base map gallery
		view.ui.add(bgExpand, "bottom-left"); 
		
		// create layer list  
		var layerList = new LayerList({
		view: view});   
		// add layer list
		view.ui.add(layerList, {
		position: "top-left"});
		
		 // create & define search widget  
//		var searchWidget = new Search({
//        view: view,
//        includeDefaultSources: false,
//        locationEnabled: false,
//        sources: [{
//          layer: Parcels,
//          searchFields: ["PM_PAR_14"],
//          displayField: "PM_PAR_14",
//          exactMatch: false,
//          outFields: ["PARCEL_ID"],
//          name: "Parcel Number",
//          placeholder: "example: RP40N02W162502",
//        }, {
//          layer: Parcels,
//          searchFields: ["PM_MAIL_NM"],
//          displayField: "PM_MAIL_NM",
//          exactMatch: false,
//          outFields: ["PM_MAIL_NM"],
//          name: "Last Name, First Name",
//          placeholder: "example: Doe, John",
//        }, {
//          layer: Addresses,
//          searchFields: ["FULLADDRSS"],
//          exactMatch: false,
//          outFields: ["*"],
//          name: "Address",
//		  placeholder: "example: 1000 Main",
 //       }]
//		});

		// add search widget  
//		view.ui.add(searchWidget, {
//		position: "top-left",
//		index: 1
		
//		}); 
		
      });
